import 'dart:convert';
import 'dart:typed_data';
import 'dart:ui' as ui;

/// Offline 24×42 tonal reference from a newly generated original aerial ocean.
/// RGB565 stores only broad color/depth shapes, NOT 4K photographic pixels.
/// The GPU synthesizes fine surface detail at the actual output resolution.
class OceanToneAtlas {
  OceanToneAtlas._();
  static const width = 24;
  static const height = 42;
  static const String encoded = '';

  static Uint8List bytes() {
    final packed = base64Decode(encoded);
    if (packed.length != width * height * 2) {
      throw StateError('Invalid ocean tonal atlas');
    }
    final rgba = Uint8List(width * height * 4);
    for (var i = 0, j = 0; i < packed.length; i += 2, j += 4) {
      final rgb565 = packed[i] | (packed[i + 1] << 8);
      final red = (rgb565 >> 11) & 31;
      final green = (rgb565 >> 5) & 63;
      final blue = rgb565 & 31;
      rgba[j] = (red << 3) | (red >> 2);
      rgba[j + 1] = (green << 2) | (green >> 4);
      rgba[j + 2] = (blue << 3) | (blue >> 2);
      rgba[j + 3] = 255;
    }
    return rgba;
  }

  static ui.Image decode() => ui.decodeImageFromPixelsSync(
      bytes(), width, height, ui.PixelFormat.rgba8888);
}
